    def trap(self, height):
        """
        :type height: List[int]
        :rtype: int
        """
        if not height:
                return 0

        left, right = 0, len(height) - 1
        leftMax, rightMax = 0, 0
        result = 0
        while left < right:
                if height[left] < height[right]:
                        if height[left] > leftMax:
                                leftMax = height[left]
                        else:
                                result += (leftMax - height[left])
                        left += 1
